INSERT INTO events (id, title, venue, area, day, time, time_short, ampm, cat, cat_label, price, free, dist, att, friends, host, host_init, about, pin_left, pin_top, pin_size) VALUES
  (1, 'Neon Warehouse', 'Basement Nine', 'Bushwick', 21, '11:00 PM', '11:00', 'PM', 'techno', 'Techno', '$25', 0, '0.8 mi', 342, 12, 'Maya Reyes', 'MR', 'Three rooms, two floors, one night. Bushwick''s biggest warehouse rave returns with a raw industrial sound system and visuals until sunrise. 21+, dress to move.', 105, 210, 44),
  (2, 'Rooftop Sunset Sessions', 'The Aerie', 'Williamsburg', 24, '6:30 PM', '6:30', 'PM', 'house', 'Rooftop', '$15', 0, '1.2 mi', 128, 10, 'Dev & Zoe', 'DZ', 'Golden-hour house music with skyline views. Natural wine bar, low-key sets, and the best sunset in Brooklyn. Come early - the roof fills fast.', 224, 175, 38),
  (3, 'Vinyl Nights: Disco', 'Groove Room', 'Bushwick', 25, '10:00 PM', '10:00', 'PM', 'house', 'House', 'Free', 1, '0.5 mi', 96, 8, 'Kai Tran', 'KT', 'All vinyl, all disco, all night. A tight basement room, a wall of records, and no phones on the floor. Free entry before 11.', 161, 330, 36),
  (4, 'Afterhours: Deep Cuts', 'Cellar 33', 'East Williamsburg', 22, '2:00 AM', '2:00', 'AM', 'techno', 'Techno', '$20', 0, '2.0 mi', 210, 12, 'Priya N.', 'PN', 'When everything else closes, this opens. Deep, hypnotic techno in a candle-lit cellar for the ones who never go home. Members + guests.', 266, 350, 40),
  (5, 'Y2K Throwback Rave', 'Palace Hall', 'Ridgewood', 26, '9:00 PM', '9:00', 'PM', 'all', 'Live', '$30', 0, '3.1 mi', 540, 12, 'Leo M.', 'LM', '2000s bangers, butterfly clips, and a giant disco ball. Full live PA, throwback visuals, and a costume contest at midnight. Dress the decade.', 63, 375, 42),
  (6, 'Backyard Beats & BBQ', 'The Lot', 'Bushwick', 22, '4:00 PM', '4:00', 'PM', 'house', 'House', 'Free', 1, '0.9 mi', 74, 7, 'Nia B.', 'NB', 'Day party done right. Smoky grills, a garden sound system, and easy house grooves till sundown. Bring a friend, BYO good vibes.', 182, 260, 34);
